    /** Largest stack (bb) at which [className] shoves from the small blind. */
    fun pushUpTo(className: String): Double = PUSH.getValue(className)

    /** Largest stack (bb) at which [className] calls a small-blind shove in the big blind. */
    fun callUpTo(className: String): Double = CALL.getValue(className)

    /** Share of all 1326 starting hands the small blind shoves at [stack] bb. */
    fun pushFraction(stack: Double): Double =
        PUSH.entries.sumOf { (k, v) -> if (v >= stack) combos(k) else 0 } / 1326.0

    private fun combos(name: String): Int = when {
        name.length == 2 -> 6
        name.endsWith("s") -> 4
        else -> 12
